// Chat detection of scheduling requests (src/schedule-detection.ts, docs/scheduled-20261115.md).
// Written before the rules were tuned. `expect: null` means the message must be sent as usual.
// For a positive case `time: null` means no time was given, so the card asks for one.
export interface DetectionCase {
  text: string;
  expect: null | {
    every: number;
    unit: "day" | "week" | "month";
    weekday?: number;
    dayOfMonth?: number;
    time: string | null;
  };
}

